per_hop.query:
SELECT DISTINCT ?actor WHERE {
  ?wonderWomanFilm wdt:P31 wd:Q11424;  # Instance of a film
                   rdfs:label "Wonder Woman"@en;
                   wdt:P577 ?wwReleaseDate.
  FILTER(YEAR(?wwReleaseDate) = 2017)

  ?anomalisaFilm wdt:P31 wd:Q11424;
                 rdfs:label "Anomalisa"@en;
                 wdt:P577 ?anomalisaReleaseDate.
  ?fargoSeries wdt:P31 wd:Q5398426;  # Instance of TV series
               rdfs:label "Fargo"@en;
               wdt:P577 ?fargoPremiereDate.

  ?wonderWomanFilm wdt:P161 ?actor.
  ?anomalisaFilm wdt:P161 ?actor.

  FILTER(?anomalisaReleaseDate > ?fargoPremiereDate)
}
LIMIT 10

SELECT DISTINCT ?actor WHERE {
  ?wonderWomanFilm wdt:P31 wd:Q11424;  # Instance of a film
                   rdfs:label "Wonder Woman"@en;
                   wdt:P577 ?wwReleaseDate.
  FILTER(YEAR(?wwReleaseDate) = 2017)

  ?anomalisaFilm wdt:P31 wd:Q11424;
                 rdfs:label "Anomalisa"@en;
                 wdt:P577 ?anomalisaReleaseDate.
  ?fargoSeries wdt:P31 wd:Q5398426;  # Instance of TV series
               rdfs:label "Fargo"@en;
               wdt:P577 ?fargoPremiereDate.

  ?wonderWomanFilm wdt:P161 ?actor.
  ?anomalisaFilm wdt:P161 ?actor.

  FILTER(?anomalisaReleaseDate > ?fargoPremiereDate)
}
LIMIT 10

SELECT DISTINCT ?actor WHERE {
  # Find actors in Wonder Woman 2017
  ?wwFilm wdt:P31 wd:Q11424; # instance of film
          wdt:P577 ?wwDate;
          wdt:P1476 "Wonder Woman"@en;
          wdt:P136 wd:Q188473; # genre action-adventure
          wdt:P161 ?actor.
  FILTER(YEAR(?wwDate) = 2017)

  # Actor also appeared in Anomalisa
  ?anomalisaFilm wdt:P31 wd:Q11424; 
                 wdt:P577 ?anomalisaDate; 
                 wdt:P1476 "Anomalisa"@en;
                 wdt:P161 ?actor.

  # Check Fargo premiere year
  ?fargoSeries wdt:P31 wd:Q5398426; # TV series
               wdt:P577 ?fargoDate;
               wdt:P1476 "Fargo"@en.
  FILTER(YEAR(?fargoDate) = 2014)

  FILTER(YEAR(?anomalisaDate) > 2014)
}
